def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fits = bins >= item
    remainder = bins % item
    return np.where(fits, -remainder, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fit_mask = bins >= item
    num_fit = np.floor(bins / item)
    remainder = bins % item
    scores = - (num_fit * remainder)
    return np.where(fit_mask, scores, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining_space = bins - item
    return np.where(remaining_space >= 0, -remaining_space, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    fits = bins >= item
